// ── Section Preview Node ───────────────────────────────────────────────────────

interface SectionPreviewProps {
    item: Section;
    index: number;
    isPreview: boolean;
    hoveredItemId: string | null;
    isActiveSectionInEdit: boolean;
    isSummarizing: boolean;
    isExpanding: boolean;
